package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64 constructor.
 */
public class Base64_Base64_TriageGen1Test {











    @Test
    public void testFullConstructor() {
        // Tests public Base64(int lineLength, byte[] lineSeparator, boolean urlSafe)
        int lineLength = 76;
        byte[] lineSeparator = "\r\n".getBytes();
        boolean urlSafe = true;
        Base64 base64 = new Base64(lineLength, lineSeparator, urlSafe);

        assertNotNull(base64);
        assertTrue("Full constructor with true should be URL safe", base64.isUrlSafe());
    }


}

